exec(open('/tmp/gen_task.py').read().split(\"out('Require\")[0])
def lemma(name, decomp, stmt, proof):
    out(f'\\nLemma {name} :')
    for i,k in enumerate(kinds):
        out('  ('+stmt(k)+ (').' if i==3 else ') /\\\\'))
    out('Proof.\\n'+proof+'\\nQed.')
    if decomp:
        for i,k in enumerate(kinds):
            out(f'Definition {name}_{k} := '+ 'proj2 ('*i+name+')'*i if False else
                f'Definition {name}_{k} := '+ ('proj1 (' if i"'!=3 else '"'')+'proj2 ('*i+name+')'*i+(')' if i"'!=3 else '"'')+'.')
lemma('fc_degree_mono',True,lambda k:f'forall e p q p\\' q\\', p <= p\\' -> q <= q\\' -> fc_degree_{k} p q e -> fc_degree_{k} p\\' q\\' e',
'''  apply fc_syntax_ind; intros; cbn in *; try lia;
    repeat match goal with H : _ /\\\\ _ |- _ => destruct H end;
    repeat split; try (eapply H; [lia|lia|assumption]);
    try (eapply H0; [lia|lia|assumption]); try (eapply H1; [lia|lia|assumption]).''')
for m, order, ty, var in [('tm','p','tm','a_Var_f'),('co','q','co','g_Var_f')]:
    op=lambda k:f'open_{k}_wrt_{m}_rec'
    def pq(s):
        return f'({s} p) q' if m=='tm' else f'p ({s} q)'
    def both(k,n,sc):
        return f'fc_degree_{k} {pq(n)} {sc}' if n else f'fc_degree_{k} p q {sc}'
    bound='p' if m=='tm' else 'q'
    varb='a_Var_b' if m=='tm' else 'g_Var_b'
    lemma(f'fc_{m}open_degree',True,lambda k:f'forall e p q n u, n <= {bound} -> fc_degree_{ty} 0 0 u ->\\n    {both(k,\"S\",\"e\")} -> {both(k,\"\",f\"({op(k)} n u e)\")}',
'''  apply fc_syntax_ind; intros; cbn in *;
    repeat match goal with H : _ /\\\\ _ |- _ => destruct H end;
    repeat split; try assumption; try (eapply H; [lia|eassumption|eassumption]);
    try (eapply H0; [lia|eassumption|eassumption]);
    try (eapply H1; [lia|eassumption|eassumption]);
    destruct lt_eq_lt_dec as [[?|?]|?]; cbn; try lia;
    eapply fc_degree_mono_'''+ty+'''; [lia|lia|eassumption].''')
    lemma(f'fc_{m}open_degree_inv',True,lambda k:f'forall e p q n u, n <= {bound} ->\\n    {both(k,\"\",f\"({op(k)} n u e)\")} -> {both(k,\"S\",\"e\")}',
'''  apply fc_syntax_ind; intros; cbn in *;
    repeat match goal with H : _ /\\\\ _ |- _ => destruct H end;
    repeat split; try assumption; try (eapply H; [lia|eassumption]);
    try (eapply H0; [lia|eassumption]); try (eapply H1; [lia|eassumption]);
    destruct lt_eq_lt_dec as [[?|?]|?] in *; cbn in *; lia.''')
    lemma(f'fc_{m}open_id',True, lambda k:f'forall e p q u, fc_degree_{k} p q e -> {op(k)} {bound} u e = e',
'''  apply fc_syntax_ind; intros; cbn in *;
    repeat match goal with H : _ /\\\\ _ |- _ => destruct H end;
    repeat match goal with H : forall _ _ _, _ |- _ => rewrite H by eassumption end;
    try reflexivity; destruct lt_eq_lt_dec as [[?|?]|?]; try reflexivity; lia.''')
    lemma(f'fc_subst_{m}open',True,lambda k:f'forall e f h n u,\\n    (forall x, fc_degree_tm 0 0 (f x)) -> (forall x, fc_degree_co 0 0 (h x)) ->\\n    fc_subst_{k} f h ({op(k)} n u e) = {op(k)} n (fc_subst_{ty} f h u) (fc_subst_{k} f h e)',
'''  apply fc_syntax_ind; intros; cbn;
    repeat match goal with H : forall _ _ _ _, _ |- _ => rewrite H by assumption end;
    try reflexivity;
    try (destruct lt_eq_lt_dec as [[?|?]|?]; reflexivity);
    symmetry; first
      [ eapply fc_'''+m+'''open_id_tm; eapply fc_degree_mono_tm; [lia|lia|auto]
      | eapply fc_'''+m+'''open_id_co; eapply fc_degree_mono_co; [lia|lia|auto] ].''')
    lemma(f'fc_{m}close_degree',True,lambda k:f'forall e p q n x, n <= {bound} ->\\n    {both(k,\"\",\"e\")} -> {both(k,\"S\",f\"(fc_close_{m}_{k} n x e)\")}',
'''  apply fc_syntax_ind; intros; cbn in *;
    repeat match goal with H : _ /\\\\ _ |- _ => destruct H end;
    repeat split; try assumption; try (eapply H; [lia|eassumption]);
    try (eapply H0; [lia|eassumption]); try (eapply H1; [lia|eassumption]);
    first [destruct lt_dec | destruct (_ == _)]; cbn in *; try lia; exact I.''')
    lemma(f'fc_{m}close_fresh',True,lambda k:f'forall e n x, x \\\\notin fc_fv_{k} (fc_close_{m}_{k} n x e) \\\\/ {(\"True\" if k==\"co\" and False else \"False\")}',
'''  (* The other variable sort can contain the same atom. *)
''') if False else None
PY
python /tmp/fc_syntax_proofs.py >/tmp/fc-new
cat /tmp/fc-new >> Task.v
rocq compile -q -Q . '' -R .rocq-deps/Metalib Metalib Task.v"

