/bin/bash -lc "sed -i '"'$d'"' /tmp/fc/FCGuess.v
cat >>/tmp/fc/FCGuess.v <<'EOF'
    all: match goal with |- context [fc_pick ?G ?S] =>
      let F := fresh \"Fpick\" in pose proof (fc_pick_spec G S) as F;
      let D := fresh \"Dpick\" in pose proof (fc_pick_dom G S) as D;
      set (x := fc_pick G S) in *
    end.
    + assert (Q : AnnTyping ((x,Tm A0)::G)
          (open_tm_wrt_tm a0 (a_Var_f x)) (open_tm_wrt_tm B (a_Var_f x))).
      { apply (fc_fresh_t_typ L); assumption. }
      assert (W : AnnCtx ((x,Tm A0)::G)) by (apply An_ConsTm; assumption).
      fc_guess_rewrite.
      rewrite fc_close_t_open_t; [reflexivity|].
      pose proof (fc_typ_free _ _ _ H1 x ltac:(fsetdec) ltac:(simpl; fsetdec)); simpl in *; fsetdec.
    + assert (Q : AnnTyping ((x,Co phi)::G)
          (open_tm_wrt_co a0 (g_Var_f x)) (open_tm_wrt_co B (g_Var_f x))).
      { apply (fc_fresh_c_typ L); assumption. }
      assert (W : AnnCtx ((x,Co phi)::G)) by (apply An_ConsCo; assumption).
      fc_guess_rewrite.
      rewrite fc_close_c_open_c; [reflexivity|].
      pose proof (fc_typ_free _ _ _ H1 x ltac:(fsetdec) ltac:(simpl; fsetdec)); simpl in *; fsetdec.
    all: try solve [
      assert (KA : AnnTyping G A1 a_Star) by (assumption || (eapply fc_typ_pi_domain; eassumption));
      assert (W : AnnCtx ((x,Tm A1)::G)) by (apply An_ConsTm; assumption);
      match goal with
      | J : forall y, y "'`notin` ?L -> AnnDefEq (y ~ Tm A1 ++ G) ?D (open_co_wrt_tm g2 (a_Var_f y))
                       (open_tm_wrt_tm ?b (a_Var_f y)) (open_tm_wrt_tm ?c (a_Var_f y)),
        E : AnnDefEq G ?D g1 A1 ?A2 |- _ =>
        pose proof (fc_fresh_t_eq L G D A1 g2 b c x H KA Dpick J) as Q;
        destruct (fc_eq_free _ _ _ _ _ E x ltac:(fsetdec) ltac:(fsetdec)) as [FA1 FA2];
        destruct (fc_eq_binder_free_t G A1 g2 D b c x ltac:(fsetdec) FA1 ltac:(fsetdec) (ex_intro _ L J));
        fc_guess_rewrite; rewrite !fc_close_t_open_t by assumption;
        erewrite fc_tcast_cofinite; [reflexivity|eapply fc_co_degree; exact E|eassumption]
      end].
    all: try solve [
      assert (KA : AnnPropWff G phi1) by
        (eapply fc_typ_cpi_domain; eassumption) ||
        (match goal with J : AnnTyping G (a_CAbs phi1 _) _ |- _ => inversion J; assumption end);
      assert (W : AnnCtx ((x,Co phi1)::G)) by (apply An_ConsCo; assumption);
      match goal with
      | J : forall y, y `notin` ?L -> AnnDefEq (y ~ Co phi1 ++ G) ?D (open_co_wrt_co g3 (g_Var_f y))
                       (open_tm_wrt_co ?b (g_Var_f y)) (open_tm_wrt_co ?c (g_Var_f y)),
        E : AnnIso G ?D g1 phi1 ?phi2 |- _ =>
        pose proof (fc_fresh_c_eq L G D phi1 g3 b c x H KA Dpick J) as Q;
        destruct (fc_iso_free _ _ _ _ _ E x ltac:(fsetdec) ltac:(fsetdec)) as [FA1 FA2];
        destruct (fc_eq_binder_free_c G phi1 g3 D b c x ltac:(fsetdec) FA1 ltac:(fsetdec) (ex_intro _ L J));
        fc_guess_rewrite; rewrite !fc_close_c_open_c by assumption;
        erewrite fc_ccast_cofinite; [reflexivity|eapply fc_iso_degree; exact E|eassumption]
      end].
  Show.
EOF
rocq repl -quiet -Q /tmp/fc '"'' -Q . '' -R .rocq-deps/Metalib Metalib -l /tmp/fc/FCGuess.v </dev/null"

