from pathlib import Path
import re
from collections import Counter
s=Path('Task.v').read_text()
do_not_remove={'FC_typechecker'}
removed=[]
while True:
    count=Counter(re.findall(r'\\bfc_\\w+',s))
    limits=[]
    for m in re.finditer(r'(?m)"'^(Definition|Lemma|Ltac) (fc_'"\\w+)\\b',s):
        form,name=m.groups()
        if count[name]"'!=1 or name in do_not_remove:
            continue
        tail=s[m.end():]
        if form=='"'Ltac':
            end=re.search(r'\\.\\n(?=\\n|\\S)',tail)
        elif form=='Definition':
            end=re.search(r'"'^'"\\s*(?:Proof\\. ["'^'"\\n]*\\bDefined\\.|Defined\\.)\\n|\\.\\n',tail,re.M)
        else:
            end=re.search(r'\\bQed\\.\\n',tail)
        if not end:
            raise ValueError(name)
        stop=m.end()+end.end()
        block=s[m.start():stop]
        if form=='Definition' and tail[end.end():].startswith('Proof.'):
            end_proof=re.search(r'\\b(?:Qed|Defined)\\.\\n',tail[end.end():])
            if not end_proof:
                raise ValueError(name)
            stop+=end_proof.end()
        limits.append((m.start(),stop))
        removed.append(name)
    if not limits:
        break
    for a,b in reversed(limits):
        s=s[:a]+s[b:]
s=re.sub(r'\\n{3,}','\\n\\n',s)
Path('/tmp/fc_trimmed_Task.v').write_text(s)
print(f'Removed {len(removed)} unused declarations. The trimmed file has {len(s.splitlines())} lines.')
print(' '.join(removed))
PY
python /tmp/fc_trim.py
diff -u Task.v /tmp/fc_trimmed_Task.v | rg '"'^[-+](Definition|Lemma|Ltac|Theorem|Proof|Qed|Defined)'"'"

